import { Suspense, ViewTransition } from 'react'
import { PageTransition } from './PageTransition'
import { ProductGrid } from './ProductGrid'
import { ProductGridSkeleton } from './ProductSkeleton'

export default function Home() {
  return (
    <PageTransition>
      <main>
        <h1>Products</h1>
        <ViewTransition name="product-grid-content" update="skeleton-reveal">
          <Suspense fallback={<ProductGridSkeleton />}>
            <ProductGrid />
          </Suspense>
        </ViewTransition>
      </main>
    </PageTransition>
  )
}
import { Suspense, ViewTransition } from 'react'
import Link from 'next/link'
import { PageTransition } from '@/app/PageTransition'
import { getProduct, products } from '@/lib/products'
import { notFound } from 'next/navigation'

async function ProductDetails({ slug }: { slug: string }) {
  await new Promise((resolve) => setTimeout(resolve, 100))
  const product = getProduct(slug)
  if (!product) notFound()

  return (
    <div className="product-info">
      <h1>{product.name}</h1>
      <p className="product-price">${product.price}</p>
      <p className="product-description">{product.description}</p>
    </div>
  )
}

function DetailsSkeleton() {
  return (
    <div className="product-info">
      <div className="skeleton-text large" />
      <div className="skeleton-text short" />
      <div className="skeleton-text" />
    </div>
  )
}

export default async function ProductPage({
  params,
}: {
  params: Promise<{ slug: string }>
}) {
  const { slug } = await params
  const product = products.find((p) => p.slug === slug)
  if (!product) notFound()

  return (
    <PageTransition>
      <main>
        <Link href="/" className="back-link" transitionTypes={['to-grid']}>
          ← Back to products
        </Link>
        <div className="product-detail">
          <ViewTransition name={`product-image-${product.slug}`} share="product-image-share">
            <div
              className="product-hero"
              style={{ backgroundColor: product.color }}
            />
          </ViewTransition>
          <ViewTransition name={`product-info-${product.slug}`} update="skeleton-reveal">
            <Suspense fallback={<DetailsSkeleton />}>
              <ProductDetails slug={slug} />
            </Suspense>
          </ViewTransition>
        </div>
      </main>
    </PageTransition>
  )
}
import Link from 'next/link'
import { ViewTransition } from 'react'
import { products } from '@/lib/products'

export function ProductGrid() {
  return (
    <div className="product-grid">
      {products.map((product) => (
        <Link
          key={product.slug}
          href={`/product/${product.slug}`}
          className="product-card"
          transitionTypes={['to-detail']}
        >
          <ViewTransition name={`product-image-${product.slug}`} share="product-image-share">
            <div
              className="product-image"
              style={{ backgroundColor: product.color }}
            />
          </ViewTransition>
          <h2>{product.name}</h2>
          <p>${product.price}</p>
        </Link>
      ))}
    </div>
  )
}
import { ViewTransition, type ReactNode } from 'react'

export function PageTransition({ children }: { children: ReactNode }) {
  return (
    <ViewTransition
      enter={{ 'to-detail': 'page-enter-forward', 'to-grid': 'page-enter-back' }}
      exit={{ 'to-detail': 'page-exit-forward', 'to-grid': 'page-exit-back' }}
    >
      {children}
    </ViewTransition>
  )
}

